INSERT INTO orders (customer_id, created_at)
SELECT i % 50, strftime('%Y-%m-%d %H:%M:%S', '2024-01-01 00:00:00', '+' || (i * 7) || ' hours') FROM n;
CREATE INDEX idx_orders_created_at ON orders (created_at);
